+/** Unit systems for byte formatting. */
+
+export interface UnitSystem {
+  /** Multiplier between adjacent suffixes. */
+  readonly base: number;
+  /** Suffixes from smallest to largest. */
+  readonly suffixes: readonly string[];
+}
+
+export const BINARY: UnitSystem = Object.freeze({
+  base: 1024,
+  suffixes: ["B", "KiB", "MiB", "GiB", "TiB"],
+});
+
+export const DECIMAL: UnitSystem = Object.freeze({
+  base: 1000,
+  suffixes: ["B", "kB", "MB", "GB", "TB"],
+});
+
+/** Splits `n` into a value and the index of the suffix that fits it. */
+export function scale(n: number, system: UnitSystem): { value: number; index: number } {
+  let value = n;
+  let index = 0;
+  while (value >= system.base && index < system.suffixes.length - 1) {
+    value /= system.base;
+    index++;
+  }
+  return { value, index };
+}
